events = []
class I(int):
    def __index__(self):
        events.append('int index')
        return 3
class Index:
    def __index__(self):
        events.append('index')
        return 1
i = iter(range(10, 17, 2))
actual = []
for repeat in range(3):
    try:
        result = i.__setstate__(-2**100)
        actual.append(('ok', result))
    except Exception as error:
        actual.append((type(error).__name__, error.args))
    actual.append((i.__length_hint__(), repr(i.__reduce__()[1][0]), next(i, 'end')))
actual.append(events)

